fn logical_or(x1: Vec<bool>, x2: Vec<bool>) -> Vec<bool> {
    // Optional check to ensure inputs are the same length.
    // You can remove this if you truly assume equal lengths.
    assert_eq!(
        x1.len(),
        x2.len(),
        "Input vectors must have the same length"
    );

    x1.into_iter()
        .zip(x2.into_iter())
        .map(|(a, b)| a || b)
        .collect()
}

